import io.wayfarer.rpg.core.*;
import java.io.*;
import java.util.*;

/** Outcomes and counterplay for the harder encounters, two-stage skills, erosion and story decisions. */
public final class ChallengeTests {
    private static int checks;
    private static void check(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
    private static void near(float a,float b,String why){check(Math.abs(a-b)<.04f,why+": "+a+" vs "+b);}
    private static ActionGame arena(int weapon,int soul){ActionGame g=new ActionGame();g.selectHero(weapon);g.bindSoul(soul,0);g.start(91);g.blocks.clear();g.enemies.clear();g.hazards.clear();g.x=560;g.y=600;g.invulnerable=0;return g;}
    private static ActionGame.Enemy mob(ActionGame g,int type,float x,float y){ActionGame.Enemy e=new ActionGame.Enemy(g.nextId++,type,x,y,1000);g.enemies.add(e);return e;}
    private static void step(ActionGame g,int frames,boolean freeze){for(int i=0;i<frames;i++){if(freeze)for(ActionGame.Enemy e:g.enemies)e.stun=1;g.hitStop=0;g.update(1f/60,new ActionGame.Input());g.signals.clear();}}
    private static byte[] edit(byte[] data,String key,String val)throws Exception{Properties p=new Properties();p.load(new ByteArrayInputStream(data));p.setProperty(key,val);ByteArrayOutputStream o=new ByteArrayOutputStream();p.store(o,"");return o.toByteArray();}
    private static void reject(byte[] bytes,String key,String val)throws Exception{boolean bad=false;try{ActionSave.decode(edit(bytes,key,val));}catch(IOException e){bad=true;}check(bad,"reject "+key);}
    private static void skills()throws Exception{
        ActionGame g=arena(0,0);ActionGame.Enemy e=mob(g,0,700,600);g.faceX=1;g.faceY=0;g.skill();float hp=e.hp;check(g.followUpWindow==2,"initial skill opens deliberate two-second link");g.skill();check(e.hp<hp&&g.followUpWindow==0,"shock follow-up reaches original stunned target");hp=e.hp;g.skill();near(e.hp,hp,"no third free attack");
        g=arena(1,0);e=mob(g,0,850,600);e.guard=40;g.skill();g.shots.clear();hp=e.hp;g.skill();check(e.guard==0&&e.hp<hp,"focused shot removes shield and damages through it");
        g=arena(2,0);e=mob(g,0,680,600);g.skill();g.blocks.add(new ActionGame.Block(610,550,30,100,0));float x=g.x;g.skill();check(g.x>x&&g.x<600&&g.free(g.x,g.y,15),"shadow thrust stops at solid obstruction");
        g=arena(0,1);e=mob(g,0,700,600);g.skill();float shield=g.soulWard;g.shots.add(new ActionGame.Shot(g.x+50,g.y,0,0,10,false));g.skill();check(g.soulWard>shield&&g.shots.isEmpty(),"radiant follow-up provides hit-earned ward and local purification");
        g=arena(0,2);e=mob(g,0,760,600);ActionGame.Enemy bystander=mob(g,0,775,630);g.skill();float second=bystander.hp;g.skill();check(e.hex==0&&bystander.hp<second&&g.corruption==30,"forbidden link spends erosion and detonates existing curse");
        g=arena(0,0);mob(g,0,700,600);g.skill();g.pause();float window=g.followUpWindow;step(g,60,true);near(g.followUpWindow,window,"pause freezes link window");ActionGame a=ActionSave.decode(ActionSave.encode(g));a.resume();a.skill();check(a.followUpWindow==0,"restored link can be used once");float after=a.enemies.get(0).hp;a.skill();near(a.enemies.get(0).hp,after,"restored link cannot repeat");g.resume();step(g,121,true);check(g.followUpWindow==0&&g.skillCd>0,"missing the window retains ordinary cooldown");
        System.out.println("PASS three skill follow-ups, cover, shield breaking, soul mutations, single use and saved window");
    }
    private static void erosion()throws Exception{
        ActionGame g=arena(0,2);mob(g,0,100,100);
        // Only legal inputs and naturally elapsed cooldowns: no direct corruption assignment.
        for(int cast=0;cast<4;cast++){g.skill();g.skill();if(cast<3)step(g,391,true);}
        check(g.corruption==100&&g.ruptureTime>0&&g.ruptureLatched,"ordinary forbidden skill rotation really reaches 100");float hp=g.hp,rt=g.ruptureTime;g.pause();step(g,120,true);near(g.ruptureTime,rt,"paused loss timer is frozen");ActionGame a=ActionSave.decode(ActionSave.encode(g));a.resume();g.resume();step(g,100,true);step(a,100,true);check(g.hp<hp,"100 erosion produces actual periodic life loss");near(a.hp,g.hp,"restore does not replay or skip rupture pulse");near(a.ruptureTime,g.ruptureTime,"rupture remaining duration preserved");
        step(g,330,true);check(g.ruptureTime==0&&g.corruption>90,"erosion does not instantly disappear after overrun");g.skill();g.skill();check(g.ruptureTime==0,"latched overrun cannot retrigger while remaining at 100");step(g,60*45,true);check(g.corruption<70&&!g.ruptureLatched,"real downtime eventually resets threshold latch");
        g=arena(0,2);mob(g,0,100,100);g.skill();float debt=g.corruption;step(g,7*60,true);near(g.corruption,debt,"eight-second delay prevents cooldown from cancelling the gained debt");step(g,3*60,true);check(g.corruption<debt&&g.corruption>debt-3,"decay is one point per second after quiet delay");
        g.corruption=100;g.ruptureTime=6;g.ruptureTick=.01f;g.ruptureLatched=true;g.hp=.5f;step(g,1,true);near(g.hp,.5f,"self erosion cannot heal or kill critical player");
        System.out.println("PASS reachable 100 erosion using legal casts, real loss, delayed decay, latch, pause and exact pulse restoration");
    }
    private static void enemies()throws Exception{
        ActionGame g=arena(0,0);ActionGame.Enemy rifle=mob(g,1,700,600);rifle.state=1;rifle.timer=.001f;rifle.aimX=-1;rifle.aimY=0;step(g,1,false);check(g.shots.size()==3,"rifle first volley has three lines of fire");g.shots.clear();rifle.timer=.51f;step(g,2,false);check(rifle.struck&&g.shots.size()==3,"rifle releases second staggered volley");
        g=arena(0,0);ActionGame.Enemy leaper=mob(g,4,760,600);ActionGame.Input move=new ActionGame.Input();move.my=-1;g.update(.05f,move);check(leaper.state==1&&leaper.targetY<600,"hunter predicts moving target before committing");float aim=leaper.aimY;g.x=300;g.update(.05f,new ActionGame.Input());near(leaper.aimY,aim,"leap aim stays locked and remains dodgeable");
        g=arena(0,0);ActionGame.Enemy burner=mob(g,5,800,600);burner.state=1;burner.timer=.001f;burner.targetX=g.x;burner.targetY=g.y;burner.aimX=-1;burner.aimY=0;step(g,1,false);check(g.hazards.size()==2,"burner lays two distinct delayed denial zones");float hp=g.hp;step(g,30,true);near(g.hp,hp,"warning period does not damage");g.pause();ActionGame saved=ActionSave.decode(ActionSave.encode(g));near(saved.hazards.get(0).warning,g.hazards.get(0).warning,"warning survives pause and save");g.resume();saved.resume();step(g,50,true);step(saved,50,true);check(g.hp<hp,"standing in armed zone really hurts");near(g.hp,saved.hp,"resumed zone maintains the same first damage time");
        g=arena(0,0);mob(g,0,100,100);g.hazards.add(new ActionGame.Hazard(0,g.x,g.y,82,1,2,15));move.mx=-1;move.my=0;for(int i=0;i<65;i++){g.enemies.get(0).stun=1;g.update(1f/60,move);}near(g.hp,g.maxHp(),"walking out of telegraphed zone avoids damage");
        g=arena(0,0);ActionGame.Enemy bell=mob(g,6,800,600),ally=mob(g,0,700,600);bell.state=1;bell.timer=.001f;ally.stun=1;step(g,1,false);check(ally.guard==24&&bell.guard==0,"bell bearer supports an ally, not itself");g.shots.clear();float health=ally.hp;g.shots.add(new ActionGame.Shot(ally.x,ally.y,0,0,20,true));step(g,1,true);near(ally.hp,health,"guard absorbs real player hit");near(ally.guard,4,"absorbed damage consumes guard");
        g=arena(0,0);ActionGame.Enemy boss=mob(g,3,700,400);for(int p=0;p<3;p++){g.hazards.clear();g.shots.clear();boss.pattern=p;boss.state=1;boss.timer=.001f;boss.stun=0;boss.targetX=g.x;boss.targetY=g.y;boss.aimX=0;boss.aimY=1;step(g,1,false);if(p==0)check(!g.hazards.isEmpty()&&g.shots.size()==12,"boss first pattern combines expanding pressure with radial shots");if(p==1)check(g.shots.size()==5&&g.hazards.isEmpty(),"boss second pattern is aimed barrage");if(p==2)check(g.hazards.size()==3&&g.shots.isEmpty(),"boss third pattern closes three staggered ground positions");}
        boss.state=0;boss.hp=400;boss.stun=0;step(g,1,false);near(boss.timer,.72f,"half-health phase shortens telegraph but does not eliminate it");
        for(int room=1;room<=5;room++){g=new ActionGame();g.start(1);g.room=room;g.generateRoom();check(g.enemies.size()==EncounterSystem.GROUPS[room-1].length,"encounter roster is populated");for(ActionGame.Enemy e:g.enemies)check(g.free(e.x,e.y,e.radius()),"all new archetypes spawn in valid space");ActionSave.decode(ActionSave.encode(g));}
        System.out.println("PASS volleys, predictive locked leaps, delayed hazards with counterplay, support shields and three boss patterns");
    }
    private static void clear(ActionGame g,int room){g.room=room;g.generateRoom();for(ActionGame.Enemy e:g.enemies)e.hp=0;g.update(.05f,new ActionGame.Input());g.signals.clear();}
    private static void story()throws Exception{
        ActionGame g=new ActionGame();g.chooseCareer(CareerSystem.DOCTOR,0,0);g.start(1);check(!g.decideStory(0,1),"undiscovered story cannot be chosen in combat");clear(g,1);check(g.storyUnlocked==1&&g.characterUnlocked[0]==1&&g.characterJobs[0]==CareerSystem.DOCTOR,"actual room clear unlocks main and current character hook");int bank=g.bank;check(g.decideStory(0,1)&&g.bank==bank+12,"story rescue choice gives one actual permanent reward");check(!g.decideStory(0,2)&&g.bank==bank+12,"cannot change decision or claim alternate reward");g.chooseReward(0);clear(g,3);int xp=g.heroXp();check(g.decideStory(2,2)&&g.heroXp()==xp+20,"evidence choice grants experience to selected role");clear(g,5);check(g.won&&g.characterUnlocked[0]==7,"boss clear unlocks character conclusion");g.returnCamp();float max=g.maxHp();check(g.decideCharacter(0,1)&&g.maxHp()==max+4,"personal protective decision creates persistent passive");float power=g.damage();check(g.decideCharacter(1,2)&&g.damage()==power+1,"personal decisive choice creates persistent attack passive");check(!g.decideCharacter(1,1),"character passive cannot be farmed");g.chooseCareer(CareerSystem.MERCHANT,0,0);check(g.characterJobs[0]==CareerSystem.DOCTOR,"changing profession cannot rewrite recorded character story");
        ActionGame a=ActionSave.decode(ActionSave.encode(g));check(a.storyChoices[0]==1&&a.storyChoices[2]==2&&a.characterChoices[0][1]==2&&a.characterJobs[0]==CareerSystem.DOCTOR,"main and character choices survive snapshot");near(a.maxHp(),g.maxHp(),"story health passive restores before HP validation");a.selectHero(1);check(a.characterJobs[1]==-1&&a.characterTrait(1)==0&&a.characterTrait(2)==0,"another character has an independent story and passives");
        check(StorySystem.ending(new int[]{1,1,1,1,1}).contains("归途有名"),"rescue ending");check(StorySystem.ending(new int[]{2,2,2,2,2}).contains("墨迹未干"),"evidence ending");check(StorySystem.ending(new int[]{1,1,1,2,2}).contains("灯下余声"),"mixed ending");
        System.out.println("PASS actual scene unlocks, two main choice rewards, independent three-beat character arcs, immutable records and endings");
    }
    private static void snapshots()throws Exception{
        ActionGame g=arena(0,0);mob(g,0,700,600);g.skill();byte[] b=ActionSave.encode(g);reject(b,"followUpWindow","3");reject(b,"hazards","19");reject(b,"storyChoice0","1");reject(b,"characterUnlocked0","2");reject(b,"characterChoice0.0","1");reject(b,"ruptureTime","1");reject(b,"enemyTactics0","41,560,380,0");reject(b,"enemyTactics0","0,560,380,1");
        // A v8 snapshot has no story or follow-up state. Existing occupational consent is preserved.
        g=arena(0,0);g.mode=ActionGame.Mode.CAMP;g.room=0;g.enemies.clear();g.experience[0]=160;g.chooseCareer(CareerSystem.DOCTOR,1,0,true);g.start(1);g.blocks.clear();g.enemies.clear();g.hp=20;mob(g,0,g.x+100,g.y);g.professionPact();b=edit(ActionSave.encode(g),"version","8");ActionGame a=ActionSave.decode(b);check(a.pactEnabled()&&a.pactTime==g.pactTime&&a.storyUnlocked==0&&a.followUpWindow==0&&a.characterJobs[0]==-1,"v8 migration preserves occupational pact and invents no story or follow-up");
        System.out.println("PASS new snapshot provenance, old v8 migration and bounded state rejection");
    }
    private static void pressure(){
        int hurtRuns=0;float damage=0;
        for(int seed=1;seed<=12;seed++){ActionGame g=new ActionGame();g.start(seed);g.room=3;g.generateRoom();g.x=560;g.y=420;float hp=g.hp;ActionGame.Input in=new ActionGame.Input();for(int t=0;t<1200&&g.mode==ActionGame.Mode.PLAY;t++){in.mx=(float)Math.cos(t*.025);in.my=(float)Math.sin(t*.025);g.update(1f/60,in);g.signals.clear();}if(g.hp<hp)hurtRuns++;damage+=hp-g.hp;}
        check(hurtRuns>=9,"simple circular running should not trivialize mixed encounters: "+hurtRuns+"/12");System.out.println("PASS pressure benchmark: basic circular movement hurt in "+hurtRuns+"/12 seeded encounters; mean loss "+String.format(Locale.ROOT,"%.1f",damage/12)+" HP (not a claim about optimal human play)");
    }
    public static void main(String[] args)throws Exception{skills();erosion();enemies();story();snapshots();pressure();System.out.println("CHALLENGE CHECKS PASSED: "+checks);}
}
